/* ---- film 103 helpers ---- */
/* orthographic 3D view: x right, y away, z up ; az = turn about z, el = elevation */
function v103(cx, cy, R, az, el = 0.32) {
  const ca = Math.cos(az), sa = Math.sin(az), ce = Math.cos(el), se = Math.sin(el);
  return v => { const X = v[0] * ca - v[1] * sa, D = v[0] * sa + v[1] * ca; return [cx + R * X, cy - R * (v[2] * ce + D * se), D]; };
}
function sph103(cx, cy, R, az, a, o = {}) {
  if (a <= 0) return v103(cx, cy, R, az, o.el);
  const P = v103(cx, cy, R, az, o.el);
  ring(cx, cy, R, o.col || C.cyan, a * 0.55, 1.6);
  const eq = []; for (let i = 0; i <= 72; i++) { const t = TAU * i / 72; eq.push(P([Math.cos(t), Math.sin(t), 0])); }
  strokePoly(eq, o.col || C.cyan, a * 0.3, 1.2, false);
  if (o.axes !== false) [[1, 0, 0, 'x'], [0, 1, 0, 'y'], [0, 0, 1, 'z']].forEach(([x, y, z, l]) => { const p = P([x * 1.18, y * 1.18, z * 1.18]), q = P([-x, -y, -z]); dashed(q[0], q[1], p[0], p[1], C.dim, a * 0.5, 1.2); lbl(l, p[0] + 10, p[1] + 6, C.dim, a, 16, 'left'); });
  return P;
}
function vec103(P, v, col, a, lab, nm = 'c', lw = 3, dx = 14, dy = -10) {
  if (a <= 0) return;
  const O = P([0, 0, 0]), p = P(v); arrow(O[0], O[1], p[0], p[1], col, a, lw); dot(p[0], p[1], 9, nm, a);
  if (lab) lblG(lab, p[0] + dx, p[1] + dy, col, a, 20, dx < 0 ? 'right' : 'left');
}
function heat103(x, y, M, cw, a, o = {}) {
  if (a <= 0) return;
  const lo = o.lo == null ? 0 : o.lo, hi = o.hi == null ? 1 : o.hi;
  M.forEach((row, i) => row.forEach((v, j) => {
    const f = clamp((v - lo) / (hi - lo)), col = v < 0 ? C.red : (o.col || C.cyan);
    fillBox(x + j * cw, y + i * cw, cw - 4, cw - 4, col, a * (o.neg ? 0.12 + 0.75 * Math.abs(v) / Math.max(Math.abs(lo), Math.abs(hi)) : 0.08 + 0.8 * f));
    rect63(x + j * cw, y + i * cw, cw - 4, cw - 4, col, a * 0.6, 1);
    if (o.txt) lbl(o.txt(v), x + j * cw + (cw - 4) / 2, y + i * cw + (cw - 4) / 2 + 6, C.white, a, o.size || 15);
  }));
}
function plot103(px, py, pw, ph, a, xr, yr, xl, yl) {
  plotAxes(px, py, pw, ph, a, xl, yl);
  return [x => px + (x - xr[0]) / (xr[1] - xr[0]) * pw, y => py - (y - yr[0]) / (yr[1] - yr[0]) * ph];
}
function series103(arr, xS, yS, col, a, lw = 3, ix = 0, iy = 1) {
  if (a <= 0) return;
  strokePoly(arr.map(r => [xS(r[ix]), yS(r[iy])]), col, a, lw, false);
}
function cell103(x, y, w, h, s, col, a, size = 20, fillA = 0.35) { if (a <= 0) return; fillBox(x, y, w, h, col, a * fillA); rect63(x, y, w, h, col, a, 1.6); lbl(s, x + w / 2, y + h / 2 + size * 0.35, C.white, a, size); }
